'use client';
import {useEffect,useMemo,useState} from 'react';
import {hotelRpc,type Membership} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import {calculateCashFlow,type CashFlowCategory} from '@/lib/cash-flow';
import {cashFlowRows,readCashConfiguration,readCashReport,type CashConfiguration,type NoCashConfiguration,type CashReport,type CashReportJournal} from '@/lib/cash-flow-report';
import {allocationMinor,cashCommand,type CashCommand} from '@/lib/cash-flow-request';
import {signedLedgerDecimal as money} from '@/lib/profit-loss';
import {downloadReport} from '@/lib/report-export';
import {ReportCsvCopy} from '@/components/report-csv-copy';
import {CashFlowSave} from '@/components/cash-flow-save';
import {CashFlowHistory} from '@/components/cash-flow-history';

function ConfigurationEditor({membership,setup,configuration,onSaved}:{membership:Membership;setup:AccountingSetup;configuration:CashConfiguration|NoCashConfiguration;onSaved:()=>void}){
 const [selected,setSelected]=useState<string[]>(configuration.configured?configuration.cash_account_ids:[]),[reason,setReason]=useState('');
 const command=useMemo(()=>{try{return cashCommand({kind:'configuration',expected:configuration.version,accounts:selected,reason});}catch{return null;}},[configuration.version,selected,reason]);
 return <section aria-label="Cash account configuration"><h3>Review cash accounts</h3><p>Select only cash and cash-equivalent accounts appropriate for this property. Receivables and clearing accounts are not automatically cash. Inactive historical accounts can be included. Saving creates a new version and starts separate classifications.</p><fieldset><legend>Cash accounts</legend>{setup.accounts.filter(a=>a.kind==='asset').map(a=><label className="field" key={a.account_id}><span><input type="checkbox" checked={selected.includes(a.account_id)} onChange={e=>setSelected(old=>e.target.checked?[...old,a.account_id]:old.filter(id=>id!==a.account_id))}/>{a.code} · {a.name}{!a.active?' · Inactive':''}</span></label>)}</fieldset><label className="field">Cash-account review reason<textarea value={reason} maxLength={500} onChange={e=>setReason(e.target.value)}/></label><CashFlowSave membership={membership} command={command} onSaved={onSaved}/></section>;
}
function JournalEditor({membership,configuration,journal,setup,onSaved}:{membership:Membership;configuration:CashConfiguration;journal:CashReportJournal;setup:AccountingSetup;onSaved:()=>void}){
 const [allocations,setAllocations]=useState<{category:CashFlowCategory;amount:string}[]>((journal.allocations??[]).map(a=>({category:a.category,amount:money(a.amount_minor)}))),[reason,setReason]=useState('');
 const prepared=useMemo(()=>{try{const command=cashCommand({kind:'review',expected:journal.review?.version??0,configuration:configuration.id,journal:journal.id,allocations:allocations.map(a=>({category:a.category,amount_minor:allocationMinor(a.amount)})),reason});if(command.kind!=='review')throw Error('Invalid review.');calculateCashFlow([{...journal,allocations:command.allocations}],configuration.cash_account_ids,'0');return {command,error:''};}catch(e){return {command:null,error:e instanceof Error?e.message:'Review the allocations.'};}},[allocations,reason,journal,configuration]);
 return <section aria-label="Classify cash movement"><h3>Classify {journal.description}</h3><p>{journal.posting_date} · Journal {journal.id}. Positive amounts are cash inflows; negative amounts are outflows. Splits must reconcile to this journal. Removing all lines reopens its classification.</p><div className="pilot-table-wrap"><table className="pilot-table"><caption>Journal lines · USD</caption><thead><tr><th>Account</th><th>Side</th><th>Amount</th></tr></thead><tbody>{journal.lines.map(l=><tr key={l.line_no}><td>{setup.accounts.find(a=>a.account_id===l.account_id)?.name??l.account_id}{configuration.cash_account_ids.includes(l.account_id)?' · Cash':''}</td><td>{l.side}</td><td>{money(l.amount_minor)}</td></tr>)}</tbody></table></div>{allocations.map((a,i)=><div className="pilot-report-filters" key={i}><label className="field">Category {i+1}<select value={a.category} onChange={e=>setAllocations(old=>old.map((v,n)=>n===i?{...v,category:e.target.value as CashFlowCategory}:v))}><option value="operating">Operating</option><option value="investing">Investing</option><option value="financing">Financing</option></select></label><label className="field">Signed USD {i+1}<input inputMode="decimal" value={a.amount} onChange={e=>setAllocations(old=>old.map((v,n)=>n===i?{...v,amount:e.target.value}:v))}/></label><button type="button" onClick={()=>setAllocations(old=>old.filter((_,n)=>n!==i))}>Remove allocation {i+1}</button></div>)}<button type="button" disabled={allocations.length>=100} onClick={()=>setAllocations(old=>[...old,{category:'operating',amount:''}])}>Add allocation</button><label className="field">Classification review reason<textarea value={reason} maxLength={500} onChange={e=>setReason(e.target.value)}/></label>{reason.length>=4&&prepared.error&&<p role="alert">{prepared.error}</p>}<CashFlowSave membership={membership} command={prepared.command as CashCommand|null} onSaved={onSaved}/></section>;
}
export function AccountingCashFlow({membership,start,end}:{membership:Membership;start:string;end:string}){
 const {tenant_id,property_id,role}=membership,allowed=role==='owner'||role==='manager';
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[latest,setLatest]=useState<CashConfiguration|NoCashConfiguration|null>(null),[selected,setSelected]=useState<CashConfiguration|null>(null),[reference,setReference]=useState(''),[report,setReport]=useState<CashReport|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(false),[revision,setRevision]=useState(0),[editAccounts,setEditAccounts]=useState(false),[journalId,setJournalId]=useState('');
 useEffect(()=>{let current=true;setSetup(null);setLatest(null);setSelected(null);setReport(null);setError('');setJournalId('');setEditAccounts(false);setLoading(allowed);
  if(allowed)Promise.all([hotelRpc('gl_setup',{p_tenant:tenant_id,p_property:property_id}),hotelRpc('cash_flow_configuration',{p_tenant:tenant_id,p_property:property_id})]).then(([s,c])=>{const parsed=readAccountingSetup(s,tenant_id,property_id),config=readCashConfiguration(c,{tenant_id,property_id});if(current){setSetup(parsed);setLatest(config);setSelected(config.configured?config:null);setReference(config.configured?config.id:'');setEditAccounts(!config.configured);}}).catch(e=>{if(current)setError(e.message);}).finally(()=>{if(current)setLoading(false);});return()=>{current=false;};
 },[tenant_id,property_id,allowed,revision]);
 useEffect(()=>{let current=true;setReport(null);setJournalId('');if(!allowed||!selected)return;setLoading(true);setError('');hotelRpc('cash_flow_ledger',{p_tenant:tenant_id,p_property:property_id,p_configuration:selected.id,p_start:start,p_end:end}).then(v=>{const parsed=readCashReport(v,{tenant_id,property_id,start,end,configuration_id:selected.id});if(current)setReport(parsed);}).catch(e=>{if(current)setError(e.message);}).finally(()=>{if(current)setLoading(false);});return()=>{current=false;};},[tenant_id,property_id,allowed,selected,start,end]);
 const [referenceRequest,setReferenceRequest]=useState<string|null>(null);
 useEffect(()=>{let current=true;if(referenceRequest===null||!allowed)return;setLoading(true);setError('');setReport(null);hotelRpc('cash_flow_configuration',{p_tenant:tenant_id,p_property:property_id,p_configuration:referenceRequest||null}).then(v=>{const c=readCashConfiguration(v,{tenant_id,property_id});if(!c.configured)throw Error('No cash accounts have been configured.');if(referenceRequest&&c.id!==referenceRequest)throw Error('Configuration reference did not match.');if(current){setSelected(c);setReference(c.id);}}).catch(e=>{if(current)setError(e.message);}).finally(()=>{if(current){setLoading(false);setReferenceRequest(null);}});return()=>{current=false;};},[tenant_id,property_id,allowed,referenceRequest]);
 if(!allowed)return <p>Cash-flow reports are available to owners and managers.</p>;
 if((setup&&(setup.tenant_id!==tenant_id||setup.property_id!==property_id))||(selected&&(selected.tenant_id!==tenant_id||selected.property_id!==property_id)))return <p role="status">Loading cash flow…</p>;
 const visible=!error&&!loading&&report?.tenant_id===tenant_id&&report.property_id===property_id&&report.start===start&&report.end===end&&report.configuration.id===selected?.id?report:null;
 const currentSetup=setup?.tenant_id===tenant_id&&setup.property_id===property_id?setup:null;
 const journal=visible?.journals.find(j=>j.id===journalId),onSaved=()=>{setReport(null);setRevision(n=>n+1);};
 return <section className="pilot-report" aria-label="Cash flow" aria-busy={loading}><div className="pilot-section-heading"><h2>Cash flow</h2><button type="button" disabled={loading} onClick={()=>setRevision(n=>n+1)}>Refresh cash flow</button></div><p>{start} through {end} (end excluded) · USD · Posted journals only. Reconcile cash-account designations and all required postings before final financial-statement use.</p>{loading&&<p role="status">Loading cash flow…</p>}{error&&<p role="alert">{error}</p>}{latest&&!latest.configured&&<p>No cash accounts are configured. An owner must review the cash-account basis first.</p>}{latest&&role==='owner'&&<button type="button" onClick={()=>{setEditAccounts(v=>!v);setJournalId('');}}>{editAccounts?'Close cash-account editor':'Edit cash accounts'}</button>}{editAccounts&&currentSetup&&latest&&role==='owner'&&<ConfigurationEditor key={tenant_id+'/'+property_id+'/'+revision} membership={membership} setup={currentSetup} configuration={latest} onSaved={onSaved}/>}{selected&&<><p>Cash-account configuration version {selected.version}: {selected.reason}</p><p>Configuration reference: {selected.id}</p><p>{selected.account_snapshot.map(a=>a.code+' · '+a.name+(!a.active?' (inactive at review)':'')).join('; ')}</p><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();setReferenceRequest(reference.trim());}}><label className="field">Saved configuration reference<input value={reference} onChange={e=>setReference(e.target.value)} placeholder="Leave empty to load latest"/></label><button type="submit" disabled={loading}>Load saved configuration</button></form></>}{visible&&<><div className="pilot-section-heading"><button type="button" onClick={()=>{try{downloadReport('cash-flow-'+property_id+'-'+start+'-'+end,cashFlowRows(visible));}catch(e){setError(e instanceof Error?e.message:'Unable to export cash flow.');}}}>Export cash-flow CSV</button><ReportCsvCopy rows={()=>cashFlowRows(visible)}/></div><p role="status">{visible.totals.classification_complete?'All posted cash movements are classified.':`Incomplete: ${visible.totals.unclassified_journals} cash movements need classification.`}</p><dl>{[['Opening cash',visible.opening_minor],['Operating',visible.totals.categories.operating],['Investing',visible.totals.categories.investing],['Financing',visible.totals.categories.financing],['Unclassified',visible.totals.unclassified_minor],['Net change',visible.net_change_minor],['Closing cash',visible.closing_minor]].map(([label,amount])=><div key={label}><dt>{label} USD</dt><dd>{money(amount)}</dd></div>)}</dl><p>{visible.totals.internal_transfer_journals} internal cash transfers excluded from inflows and outflows.</p><div className="pilot-table-wrap"><table className="pilot-table"><caption>Posted journals and cash movement · USD</caption><thead><tr><th>Date</th><th>Description</th><th>Cash change</th><th>Classification</th><th>Review</th></tr></thead><tbody>{visible.journals.map((j,i)=>{const row=visible.totals.rows[i];return <tr key={j.id}><td>{j.posting_date}</td><th scope="row">{j.description}</th><td>{money(row.cash_change_minor)}</td><td>{row.status.replaceAll('_',' ')}{j.allocations?.map((a,n)=><div key={n}>{a.category}: {money(a.amount_minor)}</div>)}</td><td>{j.review?<><span>Version {j.review.version}: {j.review.reason}</span><br/><small>{j.review.id}</small></>:null}<CashFlowHistory key={j.id} membership={membership} configuration={visible.configuration.id} journal={j.id} description={j.description}/>{role==='owner'&&['classified','unclassified'].includes(row.status)&&<button type="button" onClick={()=>{setJournalId(j.id);setEditAccounts(false);}}>Review {j.description}</button>}</td></tr>;})}</tbody></table></div>{!visible.journals.length&&<p>No posted journals in this period. This does not establish complete books.</p>}{journal&&currentSetup&&role==='owner'&&!editAccounts&&<JournalEditor key={journal.id+'/'+(journal.review?.version??0)} membership={membership} configuration={visible.configuration} journal={journal} setup={currentSetup} onSaved={()=>{setReport(null);setJournalId('');setSelected({...visible.configuration});}}/>}</>}</section>;
}


